"""Texte LLVM des formes SDWA, DPP16 et DPP8 des VOP1, VOP2 et VOPC (gfx10).

Vecteurs des tests du désassembleur de LLVM (llvm/test/MC/Disassembler/AMDGPU, Apache 2.0 avec
exception LLVM) : gfx10_vop1_sdwa.txt, gfx10_vop2_sdwa.txt, gfx10_vopc_sdwa.txt, gfx10_vopcx_sdwa.txt,
gfx10_vop1_dpp16.txt, gfx10_vop2_dpp16.txt et gfx10_vop2_dpp8.txt (wave32).
"""
import pytest

from emu import rdna2, rdna2_operands


def encoding(text):
    return bytes(int(byte, 16) for byte in text.split(","))


@pytest.mark.parametrize("data, expected", [
    ("0xf9,0x70,0xfe,0x7f,0x01,0x06,0x06,0x00",
     "v_bfrev_b32_sdwa v255, v1 dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:DWORD"),
    ("0xf9,0xb8,0x0a,0x7e,0x01,0x06,0x03,0x00",
     "v_ceil_f16_sdwa v5, v1 dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:BYTE_3"),
    ("0xf9,0x44,0x0a,0x7e,0x6a,0x06,0x86,0x00",
     "v_ceil_f32_sdwa v5, vcc_lo dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:DWORD"),
    ("0xf9,0xb8,0x0a,0x7e,0x01,0x26,0x06,0x00",
     "v_ceil_f16_sdwa v5, v1 clamp dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:DWORD"),
    ("0xf9,0x44,0x0a,0x7e,0x01,0x86,0x06,0x00",
     "v_ceil_f32_sdwa v5, v1 mul:4 dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:DWORD"),
    ("0xf9,0x70,0x0a,0x7e,0x01,0x06,0x0e,0x00",
     "v_bfrev_b32_sdwa v5, sext(v1) dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:DWORD"),
    ("0xf9,0x70,0x0a,0x7e,0x01,0x16,0x06,0x00",
     "v_bfrev_b32_sdwa v5, v1 dst_sel:DWORD dst_unused:UNUSED_PRESERVE src0_sel:DWORD"),
    ("0xf9,0xfe,0xff,0x03,0xff,0x0d,0x16,0x25",
     "v_cndmask_b32_sdwa v255, -v255, |v255|, vcc_lo dst_sel:WORD_1 dst_unused:UNUSED_SEXT src0_sel:DWORD "
     "src1_sel:WORD_1"),
    ("0xf9,0x04,0x0a,0x50,0x01,0x06,0x0e,0x06",
     "v_add_co_ci_u32_sdwa v5, vcc_lo, sext(v1), v2, vcc_lo dst_sel:DWORD dst_unused:UNUSED_PAD "
     "src0_sel:DWORD src1_sel:DWORD"),
    ("0xf9,0x04,0x04,0x7c,0x01,0x00,0x06,0x06", "v_cmp_eq_f32_sdwa vcc_lo, v1, v2 src0_sel:DWORD src1_sel:DWORD"),
    ("0xf9,0x04,0x1e,0x7d,0x01,0xfa,0x06,0x06", "v_cmp_class_f16_sdwa ttmp14, v1, v2 src0_sel:DWORD src1_sel:DWORD"),
    ("0xf9,0x04,0x24,0x7c,0x7f,0x00,0x86,0x06", "v_cmpx_eq_f32_sdwa exec_hi, v2 src0_sel:DWORD src1_sel:DWORD"),
])
def test_sdwa_follows_llvm(data, expected):
    assert rdna2_operands.text(encoding(data)) == expected


@pytest.mark.parametrize("data, expected", [
    ("0xfa,0x70,0xfe,0x7f,0x01,0xe4,0x00,0x00", "v_bfrev_b32_dpp v255, v1 quad_perm:[0,1,2,3] row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0x02,0x0a,0x7e,0x01,0x01,0x01,0x00", "v_mov_b32_dpp v5, v1 row_shl:1 row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0x70,0x0a,0x7e,0x01,0x1f,0x01,0x00", "v_bfrev_b32_dpp v5, v1 row_shr:15 row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0x70,0x0a,0x7e,0x01,0x21,0x01,0x00", "v_bfrev_b32_dpp v5, v1 row_ror:1 row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0x70,0x0a,0x7e,0x01,0x40,0x01,0x00", "v_bfrev_b32_dpp v5, v1 row_mirror row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0x70,0x0a,0x7e,0x01,0x41,0x01,0x00", "v_bfrev_b32_dpp v5, v1 row_half_mirror row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0xb8,0x0a,0x7e,0x01,0x5f,0x01,0x00", "v_ceil_f16_dpp v5, v1 row_share:15 row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0x70,0x0a,0x7e,0x01,0x61,0x01,0x00", "v_bfrev_b32_dpp v5, v1 row_xmask:1 row_mask:0x0 bank_mask:0x0"),
    ("0xfa,0x70,0x0a,0x7e,0x01,0xe4,0x08,0x00",
     "v_bfrev_b32_dpp v5, v1 quad_perm:[0,1,2,3] row_mask:0x0 bank_mask:0x0 bound_ctrl:1"),
    ("0xfa,0x70,0x0a,0x7e,0x01,0x1b,0x04,0x00",
     "v_bfrev_b32_dpp v5, v1 quad_perm:[3,2,1,0] row_mask:0x0 bank_mask:0x0 fi:1"),
    ("0xfa,0x04,0x0a,0x02,0x01,0xe4,0xf0,0xff",
     "v_cndmask_b32_dpp v5, -|v1|, -|v2|, vcc_lo quad_perm:[0,1,2,3] row_mask:0xf bank_mask:0xf"),
    ("0xe9,0x04,0x0a,0x06,0x01,0x88,0xc6,0xfa", "v_add_f32_dpp v5, v1, v2 dpp8:[0,1,2,3,4,5,6,7]"),
    ("0xea,0x00,0x00,0x50,0x00,0x77,0x39,0x05",
     "v_add_co_ci_u32_dpp v0, vcc_lo, v0, v0, vcc_lo dpp8:[7,6,5,4,3,2,1,0] fi:1"),
])
def test_dpp_follows_llvm(data, expected):
    assert rdna2_operands.text(encoding(data)) == expected


def test_reserved_dpp_control_has_no_text():
    """dpp_ctrl 0x130 (wave_shl de GCN) n'existe pas en gfx10 : pas de texte plutôt qu'un faux."""
    assert rdna2_operands.text(encoding("0xfa,0x02,0x0a,0x7e,0x01,0x30,0x01,0x00")) is None


def test_extension_word_stays_in_the_instruction():
    shader = encoding("0xf9,0x70,0x0a,0x7e,0x01,0x06,0x0e,0x00,0x00,0x00,0x81,0xbf")    # SDWA puis s_endpgm
    assert [line[36:] for line in rdna2.listing(shader)] == [
        "v_bfrev_b32_sdwa v5, sext(v1) dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:DWORD", "s_endpgm"]
